(() => {
  'use strict';
  const $ = (s, root=document) => root.querySelector(s);
  const app = $('#app');
  const CONFIG = window.CHAPPE_CONFIG || {};
  const API = CONFIG.endpoint || (CONFIG.supabaseUrl ? `${CONFIG.supabaseUrl.replace(/\/$/,'')}/functions/v1/chappe-demo` : '');
  const KEY = CONFIG.anonKey || '';
  const STORAGE = 'chappe-static-demo-v1';
  const TOKEN_STORAGE = 'chappe-static-demo-engineer-tokens';
  const FACILITIES_STORAGE = 'chappe-demo-facilities';
  const PROFILE_STORAGE = 'chappe-demo-profiles';
  const DRAFT_STORAGE = 'chappe-demo-job-draft';
  const seed = { id:'local-demo', guideStatus:'draft', guideText:'B2: target internal angle 90 degrees; signed fold rotation -90 degrees. Confirm the return flange orientation against drawing A and the reviewed model before proceeding.', issues:[] };
  const state = { session:null, mode: API && KEY ? 'connecting' : 'local', error:'', facility:'Ridgeway Fabrication', draftFacility:'', draftName:'', op:'B2', view:'overview', responding:null, uploadFiles:[], showInvite:false, invitation:null, floorMode:'guide', assistDraft:null, assistText:'', flagText:'', listeningFor:null, speechError:'' };
  const docs = [
    {name:'sensor-mount-alpha.drawing.pdf', size:'Drawing revision A', href:'assets/sensor-mount-alpha.drawing.pdf'},
    {name:'sensor-mount-alpha.bend.json', size:'Authored panel / bend manifest', href:'assets/sensor-mount-alpha.bend.json'},
    {name:'sensor-mount-alpha.final.glb', size:'Prepared final-form 3D preview (GLB, not native CAD)', href:'assets/sensor-mount-alpha.final.glb'}
  ];
  const operations = [
    {id:'B1',title:'Left flange',detail:'Routine 90° bend',guide:false},
    {id:'B2',title:'Return flange orientation',detail:'Complex · selected for detailed guidance',guide:true},
    {id:'B3',title:'Right flange',detail:'Routine 90° bend',guide:false},
    {id:'B4',title:'Top tab',detail:'Routine 90° bend',guide:false},
    {id:'B5',title:'Bottom tab',detail:'Routine 90° bend',guide:false}
  ];
  function esc(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
  function stored(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}}
  function customFacilities(){return stored(FACILITIES_STORAGE,[]).filter(x=>x&&typeof x.name==='string')}
  function profiles(){return stored(PROFILE_STORAGE,{})}
  function jobDraft(){return stored(DRAFT_STORAGE,null)}
  function invitedFacility(){return (query().get('facility')||'').slice(0,100)}
  function isPreparedFacility(){return ['Ridgeway Fabrication','Harbour Toolworks'].includes(state.facility)}
  function inviteUrl(name){return `${baseUrl()}#/manufacturer?invite=preview&facility=${encodeURIComponent(name)}`}
  function getLocal(){try{return JSON.parse(localStorage.getItem(STORAGE))||null}catch{return null}}
  function saveLocal(session){localStorage.setItem(STORAGE,JSON.stringify(session));}
  function tokens(){try{return JSON.parse(localStorage.getItem(TOKEN_STORAGE))||{}}catch{return {}}}
  function saveToken(id,token){if(!token)return; const t=tokens();t[id]=token;localStorage.setItem(TOKEN_STORAGE,JSON.stringify(t));}
  function hasToken(){return !!tokens()[state.session?.id];}
  function sessionId(){return state.session?.id||'';}
  function normalize(s){if(!s)return null;return {id:s.id||s.sessionId||'local-demo',guideStatus:s.guideStatus||'draft',guideText:s.guideText||seed.guideText,issues:Array.isArray(s.issues)?s.issues:[]};}
  async function remote(action,fields={}){
    const response=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json','Authorization':`Bearer ${KEY}`,'apikey':KEY},body:JSON.stringify({action,...fields})});
    let result;try{result=await response.json()}catch{throw new Error(`Demo service returned HTTP ${response.status}.`)}
    if(!response.ok)throw new Error(result.error||result.message||`Demo service returned HTTP ${response.status}.`);
    return result;
  }
  async function initSession(requested){
    const local=getLocal();
    if(API&&KEY){
      try{
        const result=requested ? await remote('get',{sessionId:requested}) : local?.id && !local.id.startsWith('local-') ? await remote('get',{sessionId:local.id}) : await remote('create');
        state.session=normalize(result.session||result);state.mode='live';state.error='';
        if(result.engineerToken)saveToken(state.session.id,result.engineerToken);
        saveLocal(state.session);render();return;
      }catch(e){state.error=e.message||'Demo service unavailable';state.mode='local';}
    }
    if(requested && local?.id!==requested){state.session=null;state.error='This session cannot be found in this browser. The live demo service is unavailable.';}
    else state.session=normalize(local||seed);
    render();
  }
  async function createSession(){
    if(state.mode==='live'){
      try{const r=await remote('create');state.session=normalize(r.session||r);saveToken(state.session.id,r.engineerToken);saveLocal(state.session);state.error='';render();toast('New demo session created.');return}catch(e){state.error=e.message||'Could not create a session';state.mode='local';}
    }
    state.session=normalize({...seed,id:'local-'+crypto.randomUUID()});saveLocal(state.session);render();toast('Local preview reset in this browser.');
  }
  async function mutate(action,fields){
    if(!state.session)throw new Error('Open a demo session first.');
    if(state.mode==='live'){
      const token=tokens()[sessionId()];
      if(['approve','respond'].includes(action)&&!token)throw new Error('Engineer control is unavailable in this browser. Start a new session here.');
      const result=await remote(action,{sessionId:sessionId(),...fields,...(token&&['approve','respond'].includes(action)?{engineerToken:token}:{})});
      state.session=normalize(result.session||result);saveLocal(state.session);render();return;
    }
    const s=structuredClone(state.session);
    if(action==='approve'){s.guideStatus='approved';s.guideText=fields.guideText;}
    if(action==='issue'){s.issues.push({id:crypto.randomUUID(),kind:fields.kind,operationId:fields.operationId,body:fields.body,status:'pending',holdActive:fields.kind==='flag',answer:null,createdAt:new Date().toISOString(),reportType:fields.reportType||'none',operatorOutcome:fields.operatorOutcome||null,reportSummary:fields.reportSummary||null,recommendation:fields.recommendation||null});}
    if(action==='respond'){const issue=s.issues.find(x=>x.id===fields.issueId);if(issue){issue.answer=fields.answer;issue.status='answered';issue.holdActive=fields.holdActive!==false;}}
    state.session=s;saveLocal(s);render();
  }
  async function refresh(){if(state.mode!=='live'||!sessionId())return;try{const r=await remote('get',{sessionId:sessionId()});const latest=normalize(r.session||r);if(JSON.stringify(latest)!==JSON.stringify(state.session)){state.session=latest;saveLocal(latest);render();toast('This part was updated.');}}catch(e){state.error=e.message||'Refresh failed';state.mode='local';render();}}
  function baseUrl(){return location.href.split('#')[0].split('?')[0]}
  function operatorUrl(){return `${baseUrl()}#/operator?session=${encodeURIComponent(sessionId())}`}
  const PHONE_PREVIEW_URL = 'https://henryfowlerr.github.io/SkunkWorks/#/phone-preview';
  function currentRoute(){const hash=location.hash.slice(1);return hash.split('?')[0]||'/'}
  function query(){return new URLSearchParams(location.hash.split('?')[1]||'')}
  function brand(){return `<a href="#/" class="brand" aria-label="Chappe home"><span class="brand-mark" aria-hidden="true"><i></i><i></i><i></i></span>Chappe</a>`}
  function topbar(route){const phoneLink=route==='/'?'#/phone-preview':`#/operator?session=${encodeURIComponent(sessionId())}`;return `<header class="topbar">${brand()}<nav class="top-links" aria-label="Primary"><a class="optional" href="#/" ${route==='/'?'aria-current="page"':''}>Why Chappe</a><a href="#/engineer" ${route==='/engineer'?'aria-current="page"':''}>Engineering</a><a class="optional" href="#/manufacturer" ${route==='/manufacturer'?'aria-current="page"':''}>Manufacturing</a><a class="button slim" href="${phoneLink}">Open phone view ↗</a></nav><details class="mobile-nav"><summary>Menu</summary><nav aria-label="Mobile primary"><a href="#/" ${route==='/'?'aria-current="page"':''}>Why Chappe</a><a href="#/engineer" ${route==='/engineer'?'aria-current="page"':''}>Engineering</a><a href="#/manufacturer" ${route==='/manufacturer'?'aria-current="page"':''}>Manufacturing</a><a href="${phoneLink}">Open phone view ↗</a></nav></details></header>`}
  function banner(){const live=state.mode==='live';return `<div class="storage-banner ${live?'live':state.error?'error':''}"><strong>${live?'Live demo session':'Local preview · saved in this browser only'}</strong>${live?' · Guide approval and floor issues sync across devices.':' · QR link and issues will not sync to another device.'}${state.error?` <span role="alert">Service: ${esc(state.error)}</span>`:''}</div>`}
  function status(text,kind){return `<span class="status ${kind}">${esc(text)}</span>`}
  function toast(message){const old=$('.toast');if(old)old.remove();const el=document.createElement('div');el.className='toast';el.role='status';el.textContent=message;document.body.append(el);$('#announcement').textContent=message;setTimeout(()=>el.remove(),3500)}
  function buildAssistDraft(value){const question=String(value||'').trim().replace(/\s+/g,' ');const guide=state.session?.guideText||seed.guideText;const recommendation='Review whether Drawing A and the released B2 guide need a clearer labelled reference face before the next revision.';return {question,answer:`The released B2 guidance says: “${guide}” Check the return flange against Drawing A and the reviewed model. This source-bound response does not confirm tooling clearance or authorise the operation if the reference is still unclear.`,reportSummary:'Operator asked for help with the released B2 guidance and reports that the response was sufficient to continue.',recommendation,body:`ASSIST REPORT — operator reports resolved.\nOperator statement: ${question}\nSuggested improvement: clarify the B2 reference face in the released guide.`.slice(0,500),reportType:'assist',operatorOutcome:'resolved'};}
  function buildFlagDraft(value){const question=String(value||'').trim().replace(/\s+/g,' ');const recommendation='Engineering should review the B2 reference face, released wording, and any required guide or drawing revision before authorising a restart.';return {question,reportSummary:'Operator raised a hard-stop issue at B2 and requested immediate engineering review.',recommendation,body:`RED FLAG — hard stop; immediate review.\nOperator statement: ${question}\nSuggested investigation: confirm the B2 reference face and update the released guide if needed.`.slice(0,500),reportType:'escalation',operatorOutcome:'blocked'};}
  function issueMeta(issue){const body=String(issue?.body||'');const red=issue?.kind==='flag'||issue?.reportType==='escalation'||body.startsWith('RED FLAG');const assisted=issue?.reportType==='assist'||body.startsWith('ASSIST REPORT');const resolved=issue?.operatorOutcome==='resolved'||body.startsWith('ASSIST REPORT');return {red,assisted,resolved};}
  function issueIsHeld(issue){return issue?.holdActive!==false&&!issueMeta(issue).resolved;}
  function urgentIssues(){return (state.session?.issues||[]).filter(issue=>issueMeta(issue).red&&!issue.answer&&issue.status!=='answered');}
  function improvementReports(){return (state.session?.issues||[]).filter(issue=>issueMeta(issue).assisted&&!issueMeta(issue).red);}
  let floorRecognition=null;
  function startFloorDictation(target){if(floorRecognition){floorRecognition.stop();return;}const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SpeechRecognition){state.speechError='Voice input is not available in this browser. Type the message instead.';state.floorMode=target;render();return;}const field=target==='assist'?'assistText':'flagText';const input=target==='assist'?$('#floor-assist-text'):$('#floor-flag-text');if(input)state[field]=input.value;const recognition=new SpeechRecognition();recognition.lang=navigator.language||'en';recognition.interimResults=false;recognition.onresult=event=>{const transcript=event.results?.[0]?.[0]?.transcript?.trim();if(transcript)state[field]=[state[field].trim(),transcript].filter(Boolean).join(' ');};recognition.onerror=event=>{state.speechError=event.error==='not-allowed'?'Microphone access was denied. Type the message instead.':'Voice input stopped without a transcript. Type the message instead.';};recognition.onend=()=>{floorRecognition=null;state.listeningFor=null;render();};state.speechError='';state.listeningFor=target;try{recognition.start();floorRecognition=recognition;render();}catch{floorRecognition=null;state.listeningFor=null;state.speechError='Voice input could not start. Type the message instead.';render();}}
  function model(active='B2'){
    const colors={B1:'var(--ch-schematic-line)',B2:active==='B2'?'var(--ch-action)':'var(--ch-schematic-line)',B3:'var(--ch-schematic-line)',B4:'var(--ch-schematic-line)',B5:'var(--ch-schematic-line)'};
    return `<div class="model-frame"><svg viewBox="0 0 540 310" role="img" aria-label="Illustrative flat layout of the prepared Sensor Mount SKW-SM-104; selected bend ${esc(active)}. This is an authored panel diagram, not a physical forming simulation."><defs><pattern id="dots" width="10" height="10" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".8" fill="var(--ch-border)"/></pattern></defs><rect width="540" height="310" fill="url(#dots)"/><g fill="var(--ch-schematic-fill)" stroke="var(--ch-schematic-stroke)" stroke-width="1.7"><rect x="165" y="70" width="245" height="164"/><rect x="114" y="70" width="51" height="164"/><rect x="78" y="70" width="36" height="164"/><rect x="410" y="70" width="53" height="164"/><rect x="250" y="30" width="80" height="40"/><rect x="255" y="234" width="70" height="37"/></g><g stroke-width="5" stroke-linecap="round"><path d="M165 72v160" stroke="${colors.B1}"/><path d="M114 72v160" stroke="${colors.B2}"/><path d="M410 72v160" stroke="${colors.B3}"/><path d="M251 70h79" stroke="${colors.B4}"/><path d="M255 234h70" stroke="${colors.B5}"/></g><g fill="var(--ch-text)" font-family="-apple-system,Arial,sans-serif" font-size="13" font-weight="700"><text x="216" y="156">BASE · 120 × 80</text><text x="126" y="58">B1</text><text x="75" y="58">B2</text><text x="414" y="58">B3</text><text x="340" y="48">B4</text><text x="332" y="262">B5</text></g></svg></div><div class="model-caption">Prepared authored flat layout from SKW-SM-104 manifest · not a press-brake sequence or safety validation.</div>`
  }
  function brandMorphScene(){return `<section class="brand-morph" aria-label="Chappe signal forms resolve into the Chappe wordmark as the page scrolls"><div class="brand-morph-sticky"><canvas id="brand-morph-canvas" class="brand-morph-canvas" width="1440" height="810" role="img" aria-label="Six Chappe signal forms continuously transform into the Chappe wordmark"><span class="sr-only">Six Chappe signal forms resolve into the Chappe wordmark.</span></canvas></div></section>`}
  function landing(){return `${topbar('/')}<main class="landing">
    <section class="hero shell" aria-labelledby="hero-title">
      <h1 id="hero-title">Make the handoff<br> <em>make sense.</em></h1>
      <p class="intro">Give the workshop the right context for the difficult parts. Keep the engineer in control of what gets released.</p>
      <div class="hero-actions"><a class="button pill" href="#/engineer">Explore the demo <span aria-hidden="true">↗</span></a><a class="text-link" href="#/phone-preview">See the phone view <span aria-hidden="true">↗</span></a></div>
    </section>
    ${brandMorphScene()}
    <figure class="hero-figure reveal"><div class="hero-product" role="img" aria-label="Concept Chappe workspace: an engineer compares documented facility support, conflict, and unknown evidence beside a prepared part diagram."><div class="hero-product-bar"><span class="hero-product-brand">Chappe <span>/</span> Sensor Mount</span><span>Job 1042 <span class="hero-product-sep">·</span> Drawing A <span class="hero-product-sep">·</span> Draft</span></div><div class="hero-product-body"><div class="hero-product-left"><span class="hero-product-kicker">Receiving facility / Ridgeway Fabrication</span><strong>Know what the workshop can support.</strong><div class="hero-product-line"><span>2.0 mm sheet thickness</span><b class="hp-support">Documented support</b></div><div class="hero-product-line"><span>80 mm bend line</span><b class="hp-support">Documented support</b></div><div class="hero-product-line"><span>B2 return flange access</span><b class="hp-unknown">Unknown · confirm setup</b></div><span class="hero-product-foot">Prepared example · evidence stays visible</span></div><div class="hero-product-right">${model('B2')}<span class="hero-product-marker">B2 / Selected operation</span></div></div></div></figure>
    <section class="chapter shell" aria-labelledby="journey-title"><div class="chapter-lead reveal"><h2 id="journey-title">The detail matters<br>after the drawing leaves.</h2><p class="lead">Follow the prepared Sensor Mount example from facility selection to the exact operation on the floor. Every claim keeps its source and scope.</p></div>
      <div class="sequence" aria-label="The Chappe handoff"><article class="reveal"><div class="num">01</div><h3>Check the facility.</h3><p>Compare drawing requirements with recorded facts. Show documented support, conflict, and unknown separately.</p></article><article class="reveal"><div class="num">02</div><h3>Review the difficult work.</h3><p>Give B2 extra guidance; let routine operations stay routine. An engineer corrects the wording before release.</p></article><article class="reveal"><div class="num">03</div><h3>Release to the floor.</h3><p>Put a QR beside the drawing. The phone opens the approved operation and its release context.</p></article><article class="reveal"><div class="num">04</div><h3>Resolve it together.</h3><p>An operator flags B2. Engineering sees the issue in context and approves the answer.</p></article></div>
    </section>
    <section class="object-chapter" aria-labelledby="object-title"><div class="shell object-layout"><div class="object-copy reveal"><h2 id="object-title">Go straight to the bend that needs a closer look.</h2><p>Choose B2 on the part. Its source and uncertainty travel with the reviewed guidance. The other bends remain easy to find without a wall of instructions.</p><a class="text-link" href="#/review">Inspect the review desk <span aria-hidden="true">↗</span></a></div><div class="object-scene" aria-label="Illustrative technical rendering of the prepared Sensor Mount. B2 is highlighted; this is not a forming simulation."><svg class="object-part" viewBox="0 0 700 560" role="img" aria-label="Illustrative metal Sensor Mount with the B2 return flange highlighted"><path d="M162 258 428 168 580 292 316 386Z" fill="var(--ch-metal-light)" stroke="var(--ch-surface)" stroke-width="3"/><path d="M316 386 580 292 580 339 316 433Z" fill="var(--ch-metal-dark)" stroke="var(--ch-border-strong)" stroke-width="2"/><path d="M162 258 316 386 316 433 162 304Z" fill="var(--ch-metal-mid)" stroke="var(--ch-border)" stroke-width="2"/><path d="M162 258 116 238 116 285 162 304Z" fill="var(--ch-action-tint)" stroke="var(--ch-action)" stroke-width="3"/><path d="M116 238 162 258 316 386 274 369Z" fill="var(--ch-action)" stroke="var(--ch-action-hover)" stroke-width="2"/><path d="M428 168 462 155 612 274 580 292Z" fill="var(--ch-metal-mid)" stroke="var(--ch-border)" stroke-width="2"/><circle cx="314" cy="268" r="13" fill="var(--ch-metal-dark)"/><circle cx="436" cy="225" r="13" fill="var(--ch-metal-dark)"/><circle cx="459" cy="310" r="13" fill="var(--ch-metal-dark)"/></svg><div class="object-label"><span class="object-pulse"></span><strong>B2</strong><span>Return flange orientation</span></div><div class="object-caption">Prepared part illustration · no physical forming validation</div></div></div></section>
    <section class="preview-qr-section shell" aria-labelledby="preview-qr-title"><div class="preview-qr-copy reveal"><h2 id="preview-qr-title">Scan into the operation.</h2><p>This permanent QR opens a read-only prepared guide for Sensor Mount B2. A reviewed live demo session gets its own release QR after engineer approval.</p><a class="button pill" href="#/phone-preview">Open phone preview <span aria-hidden="true">↗</span></a><a class="preview-qr-url" href="${PHONE_PREVIEW_URL}">${PHONE_PREVIEW_URL}</a></div><div class="preview-qr-art reveal"><a href="${PHONE_PREVIEW_URL}" aria-label="Open the read-only Chappe phone preview"><img src="assets/phone-preview-qr.svg" width="320" height="320" alt="QR code for the read-only Chappe Sensor Mount phone preview"></a><span>Prepared B2 preview · read only</span><a href="assets/phone-preview-qr.svg" download="chappe-phone-preview-qr.svg">Download QR label</a></div></section>
    <section class="trust-chapter shell" aria-labelledby="trust-title"><div class="trust-intro reveal"><h2 id="trust-title">A clear answer includes<br>what we don’t know.</h2><p>Chappe’s prepared comparison reports documented support and conflict only for the facts in its source packet. B2 tooling reach remains unknown until a person confirms it.</p></div><div class="trust-list reveal"><div class="trust-state support"><strong>Documented support</strong><span>Recorded profile meets the stated value.</span></div><div class="trust-state conflict"><strong>Documented conflict</strong><span>Recorded profile contradicts a requirement.</span></div><div class="trust-state unknown"><strong>Unknown</strong><span>Evidence is missing or outside the check.</span></div></div></section>
    <section class="final-chapter"><div class="shell reveal"><h2>See the complete handoff.</h2><p>A five-minute journey from documented facility facts to an engineer-approved response on the floor.</p><a class="button pill" href="#/engineer">Start with engineering <span aria-hidden="true">↗</span></a></div></section>
    </main><footer class="shell footer"><span>Chappe · A SkunkWorks project</span><span>Prepared synthetic Sensor Mount example · Demonstration only</span></footer>`}
  function nav(which){if(which==='manufacturer')return `<aside class="sidebar" aria-label="Manufacturer sections"><button class="side-link" data-scroll="facility-record">Facility profile</button><button class="side-link" data-scroll="received-work">Received work</button><button class="side-link" data-scroll="floor-conversation">Questions and flags</button></aside>`;return `<aside class="sidebar" aria-label="Engineering sections"><a class="side-link ${which==='engineer'?'active':''}" href="#/engineer">Jobs</a><a class="side-link ${which==='engineer-job'?'active':''}" href="#/engineer/job">Sensor Mount</a><a class="side-link ${which==='engineer-new'?'active':''}" href="#/engineer/new">New job draft</a><a class="side-link ${which==='review'?'active':''}" href="#/review">Guide review</a><a class="side-link ${which==='issues'?'active':''}" href="#/issues">Floor issues</a><a class="side-link ${which==='qr'?'active':''}" href="#/qr">QR / handoff</a></aside>`}
  function wrap(which,body){return `${topbar(which.startsWith('engineer')||['review','issues','qr'].includes(which)?'/engineer':'/'+which)}${banner()}<div class="workspace">${nav(which)}<main class="work-main"><div class="work-max">${body}</div></main></div>`}
  function workHead(_kicker,title,description,buttons=''){return `<div class="work-top"><div><h1>${title}</h1><p>${description}</p></div><div class="work-actions">${buttons}</div></div>`}
  function metadata(){return `<div class="meta-strip"><span><strong>Job</strong> <span class="mono">1042</span></span><span><strong>Part</strong> <span class="mono">SKW-SM-104</span></span><span><strong>Source</strong> Drawing rev A</span><span><strong>Facility</strong> ${esc(state.facility)}</span><span><strong>Guide</strong> ${state.session?.guideStatus==='approved'?'Release 1 · engineer approved':'Draft · awaiting approval'}</span></div>`}
  function uploadedRows(files=state.uploadFiles){return files.length ? `<ul class="file-rows">${files.map(f=>`<li><strong>${esc(f.name)}</strong><span>${esc((f.size/1048576).toFixed(1))} MB · selected in this browser only</span></li>`).join('')}</ul>` : `<p class="upload-empty">No files selected in this browser.</p>`}
  function facilityOptions(){return ['Ridgeway Fabrication','Harbour Toolworks',...customFacilities().map(f=>f.name)].map(name=>`<option value="${esc(name)}" ${state.facility===name?'selected':''}>${esc(name)}</option>`).join('')}
  function invitePanel(){const i=state.invitation;return `<div class="invite-panel"><div class="eyebrow">New manufacturer / local preview</div><h3>Add a receiving facility</h3><p>Enter the contact, then copy a preview link or open an email draft. This Pages demo cannot create an account or send mail; the live invitation service runs in the Next app.</p><form id="invite-form" class="invite-form"><label class="field"><span>Manufacturer name</span><input name="name" required maxlength="100" placeholder="e.g. Northline Fabrication"></label><label class="field"><span>Contact email</span><input name="email" type="email" required maxlength="200" placeholder="team@example.com"></label><button class="button" type="submit">Create preview invitation →</button></form>${i?`<div class="invite-result"><strong>Invitation preview for ${esc(i.name)}</strong><p>Copy this link into an email. The recipient can complete a local capability form; their responses will not sync back to this engineer page.</p><div class="link-field"><input id="invite-link" readonly value="${esc(i.url)}" aria-label="Manufacturer preview link"><button class="button secondary slim" id="copy-invite">Copy link</button></div><a class="text-link" href="mailto:${encodeURIComponent(i.email)}?subject=${encodeURIComponent('Chappe manufacturer invitation preview')}&body=${encodeURIComponent(`Open this Chappe onboarding preview: ${i.url}

This is a demo link; account creation and profile sharing are not active on GitHub Pages.`)}">Open email draft ↗</a></div>`:''}</div>`}
  function draftFacilityOptions(value){return ['Ridgeway Fabrication','Harbour Toolworks',...customFacilities().map(f=>f.name)].map(name=>`<option value="${esc(name)}" ${value===name?'selected':''}>${esc(name)}</option>`).join('')}
  function engineer(){const draft=jobDraft();return wrap('engineer',`${workHead('','Engineering','Open a job or start a new one with its source files.',`<a class="button secondary" href="#/engineer/new">New job draft</a>`)}<div class="dashboard-grid"><section class="dashboard-projects" aria-labelledby="jobs-title"><div class="dashboard-heading"><h2 id="jobs-title">Jobs</h2><span>1 prepared example${draft?' · 1 local draft':''}</span></div><a class="project-row" href="#/engineer/job"><span><strong>Sensor Mount</strong><small>SKW-SM-104 · Job 1042 · ${esc(state.facility)}</small></span>${status(state.session?.guideStatus==='approved'?'Release 1 approved':'Draft for review',state.session?.guideStatus==='approved'?'good':'warn')}<span class="project-arrow" aria-hidden="true">↗</span></a>${draft?`<a class="project-row" href="#/engineer/new"><span><strong>${esc(draft.name)}</strong><small>${esc(draft.files.length)} source file${draft.files.length===1?'':'s'} · saved in this browser</small></span>${status('Local draft','neutral')}<span class="project-arrow" aria-hidden="true">↗</span></a>`:''}<p class="scope-copy">Sensor Mount is the prepared five-minute journey. Local drafts do not run a facility check or generate guidance.</p></section><section class="dashboard-intake" aria-labelledby="intake-title"><div class="dashboard-heading"><h2 id="intake-title">Start with your files</h2></div><p>Drop CAD or technical drawings to begin a local draft.</p><div id="file-drop" class="file-drop" role="group" aria-label="Choose or drop CAD and technical drawing files"><div class="file-drop-symbol" aria-hidden="true">＋</div><strong>Drop files here</strong><span>CAD model exports and technical drawings</span><label class="button secondary" for="source-files">Choose files</label><input id="source-files" type="file" multiple accept=".sldprt,.sldasm,.ipt,.iam,.step,.stp,.iges,.igs,.dxf,.dwg,.stl,.obj,.glb,.pdf,application/pdf" class="sr-only"></div>${state.uploadFiles.length?`${uploadedRows()}<a class="button pill" href="#/engineer/new">Continue draft →</a>`:'<p class="scope-copy">Files remain in this browser. This Pages demo does not upload or interpret them.</p>'}</section></div>`)}
  function engineerNew(){const saved=jobDraft();const files=state.uploadFiles.length?state.uploadFiles:saved?.files||[];const defaultName=state.draftName||saved?.name||files[0]?.name.replace(/\.[^.]+$/,'')||'';const selected=state.draftFacility||saved?.facility||'';return wrap('engineer-new',`${workHead('','New job draft','Name the job, review the selected files and choose a manufacturer.',`<a class="button secondary" href="#/engineer">All jobs</a>`)}<form id="draft-form" class="draft-form"><label class="field"><span>Project name</span><input name="name" required maxlength="100" value="${esc(defaultName)}" placeholder="Part or project name"></label><div id="file-drop" class="file-drop" role="group" aria-label="Choose or drop CAD and technical drawing files"><div class="file-drop-symbol" aria-hidden="true">＋</div><strong>Drop files here</strong><span>CAD model exports and technical drawings</span><label class="button secondary" for="source-files">Choose files</label><input id="source-files" type="file" multiple accept=".sldprt,.sldasm,.ipt,.iam,.step,.stp,.iges,.igs,.dxf,.dwg,.stl,.obj,.glb,.pdf,application/pdf" class="sr-only"></div>${uploadedRows(files)}<label class="field"><span>Manufacturer</span><select id="draft-facility" name="facility"><option value="">Choose later</option>${draftFacilityOptions(selected)}</select></label><button class="button pill" type="submit" ${files.length?'':'disabled'}>Save local draft</button><p class="scope-copy">Only the project name and file names are saved in this browser. File contents are not uploaded or analysed. The prepared Sensor Mount job is the only example with a facility comparison and reviewable guide.</p></form>`)}
  function engineerJob(){return wrap('engineer-job',`${workHead('','Sensor Mount','Prepared Job 1042 · select a workshop and review the exact guidance before release.',`<a class="button secondary" href="#/engineer">All jobs</a><button class="button secondary" id="new-session">New demo session</button><a class="button" href="#/review">Review guide →</a>`)}${metadata()}<section class="section desk-section"><div class="section-head"><div><h2>Drawing and design files</h2><p>Inspect the prepared source packet for this example.</p></div></div><div class="source-workbench"><div class="source-files"><h3>Prepared sources</h3><ul class="source-list">${docs.map(d=>`<li><strong>${esc(d.name)}</strong><span>${esc(d.size)}</span><a href="${d.href}" target="_blank" rel="noopener">Open ↗</a></li>`).join('')}</ul><p class="scope-copy">New files form a separate local draft; they do not change this prepared example.</p><a class="text-link" href="#/engineer/new">Start a new job draft ↗</a></div><div class="source-model">${model()}</div></div></section><section class="section desk-section"><div class="section-head"><div><h2>Choose the workshop</h2><p>Prepared profile facts inform this example. Newly added facilities remain unknown until verified data is connected.</p></div></div><div class="facility-control"><label class="field"><span>Manufacturer</span><select id="facility" ${state.session?.guideStatus==='approved'?'disabled title="This demo release is already approved for Ridgeway Fabrication"':''}>${facilityOptions()}</select></label><button class="button secondary" id="add-facility" type="button" aria-expanded="${state.showInvite}" ${state.session?.guideStatus==='approved'?'disabled title="Start a new demo session to choose a different facility"':''}>＋ Add manufacturer</button></div>${state.showInvite?invitePanel():''}<div id="facility-results">${facilityResults()}</div>${state.session?.guideStatus==='approved'?'<p class="scope-copy">This released example is fixed to its selected facility. Start a new demo session to compare another workshop.</p>':''}</section><section class="section desk-section"><div class="section-head"><div><h2>Review the difficult operation</h2><p>B2 is proposed for detailed floor guidance. The engineer can correct its wording and approve the release.</p></div><a class="button" href="#/review">Open review desk →</a></div><div class="decision-row"><strong>B2 · Return flange orientation</strong>${status(state.session?.guideStatus==='approved'?'Engineer approved':'Draft proposal',state.session?.guideStatus==='approved'?'good':'warn')}</div><p class="scope-copy">Tooling reach remains unknown; the guide is not a physical suitability certificate. Routine bends remain selectable without detailed instructions.</p></section>`)}
  function facilityResults(){if(!isPreparedFacility())return `<div class="result-row"><div><strong>2.0 mm sheet thickness</strong><p>Drawing A · material thickness</p></div><div class="source">No confirmed profile linked to this demo facility.</div>${status('Unknown','warn')}</div><div class="result-row"><div><strong>80 mm bend line and B2 setup</strong><p>Authored manifest and drawing A</p></div><div class="source">Manufacturer onboarding is local to the recipient browser.</div>${status('Unknown','warn')}</div><p class="evidence-followup">No confirmed capability profile for ${esc(state.facility)}. Choose a prepared facility to continue this example.</p>`;const harbour=state.facility==='Harbour Toolworks';return `<div class="result-row"><div><strong>2.0 mm sheet thickness</strong><p>Drawing A · material thickness</p></div><div class="source">${harbour?'Profile v2: sheet capacity to 1.6 mm':'Profile v3: sheet capacity to 3.0 mm'}</div>${status(harbour?'Documented conflict':'Documented support',harbour?'bad':'good')}</div><div class="result-row"><div><strong>80 mm bend line</strong><p>Authored bend manifest · B2 hinge length</p></div><div class="source">${harbour?'Profile v2: bend length to 400 mm':'Profile v3: bend length to 500 mm'}</div>${status('Documented support','good')}</div><div class="result-row"><div><strong>B2 return flange access</strong><p>Drawing A + authored panel layout · setup reach needs human confirmation</p></div><div class="source">No setup or tooling reach record for the return.</div>${status('Unknown · confirm setup','warn')}</div><p class="evidence-followup">${harbour?'The documented 1.6 mm limit conflicts with the drawing’s 2.0 mm requirement. Change the facility, profile evidence, or design before release.':'B2 tooling reach is still unknown. Confirm the setup with the facility before manufacturing.'}</p>`}
  function review(){const s=state.session||seed;const approved=s.guideStatus==='approved';const blocked=state.facility==='Harbour Toolworks'||!isPreparedFacility();return wrap('review',`${workHead('Engineer workspace / review','Guide review','Decide exactly what the operator receives. Prepared proposal; engineer approval is the release gate.',`<a class="button secondary" href="#/engineer/job">View sources</a><button class="button" id="publish-top" ${approved||blocked||(!hasToken()&&state.mode==='live')?'disabled title="Approval unavailable until the draft, facility and engineer access are ready"':''}>${approved?'Release 1 approved':blocked?'Resolve facility conflict':'Approve & publish'}${approved?'':' →'}</button>`)}${metadata()}<section class="section"><div class="review-layout"><div><div class="section-head"><div><h2>Operations</h2><p>One detailed card; routine bends stay navigable.</p></div></div><div class="operation-list">${operations.map(o=>`<button class="operation-row ${state.op===o.id?'selected':''}" data-op="${o.id}" aria-pressed="${state.op===o.id}"><span><strong>${o.id} · ${o.title}</strong><small>${o.detail}</small></span>${o.guide?status(s.guideStatus==='approved'?'Approved guide':'Draft suggestion',s.guideStatus==='approved'?'good':'warn'):status('No detail card','neutral')}</button>`).join('')}</div></div><div class="review-inspector"><div class="eyebrow">Selected operation / ${esc(state.op)}</div><h2 style="font-size:27px;letter-spacing:-.04em;margin:8px 0 5px">${esc(operations.find(o=>o.id===state.op)?.title)}</h2>${model(state.op)}${state.op==='B2'?`<div class="note warn"><strong>Source and uncertainty.</strong> Drawing A gives a 90° internal-angle target. The authored manifest maps B2 to the left return. ${approved?'This is the engineer-approved wording for Release 1.':'The wording below is a prepared demo proposal.'} It does not validate tooling clearance.</div><label class="field"><span>${approved?'Approved floor wording':'Proposed floor wording · engineer can correct'}</span><textarea id="guide-text" maxlength="1000" ${approved?'readonly':''}>${esc(s.guideText)}</textarea><small>The exact approved wording is shown on the operator guide. This release is immutable once approved.</small></label><label class="checkline"><input type="checkbox" checked disabled> Include detailed guidance for B2</label><div class="work-actions"><button class="button" id="publish" ${approved||blocked||(!hasToken()&&state.mode==='live')?'disabled title="Approval unavailable until the draft, facility and engineer access are ready"':''}>${approved?'Release 1 approved':blocked?'Resolve facility conflict':'Approve & publish'}${approved?'':' →'}</button><a class="button secondary" href="#/qr">Preview handoff</a></div>${!hasToken()&&state.mode==='live'?'<div class="note warn">This browser has no engineer token for this session. Open the engineer workspace and start a new session to approve; the QR never carries the token.</div>':''}`:`<div class="note">This is a routine area. It stays in the operation chooser but receives no detailed instruction card. Select B2 for the proposed guidance.</div>`}</div></div></section>`)}
  function manufacturer(){const invited=invitedFacility();const name=invited||state.facility;const prepared=['Ridgeway Fabrication','Harbour Toolworks'].includes(name);const profile=profiles()[name]||{};const ridge=name==='Ridgeway Fabrication';return wrap('manufacturer',`${workHead(invited?'Manufacturer / invitation preview':'Manufacturer / prepared profile',esc(name),invited?'Complete the workshop information below. This link previews onboarding; it does not create an account or send details to engineering.':'See the received example and the facility facts that engineering compares.',``)}${invited?`<div class="invitation-notice"><strong>Invitation preview</strong><span>Opened from an engineer-generated link. This page is available without sign-in; saved details stay in this browser only.</span></div>`:metadata()}<section class="section desk-section" id="facility-record"><div class="section-head"><div><h2>${prepared?'Documented example profile':'Tell engineering about this workshop'}</h2><p>${prepared?'These prepared facts support only the comparisons shown for Job 1042. Edit the local draft below to explore onboarding; it does not change those documented facts.':'Record equipment and limits for a future engineer review. This form is a local preview and makes no verified capability claim.'}</p></div></div>${prepared?`<table class="info-table"><thead><tr><th>Recorded capability</th><th>Value</th><th>Evidence</th></tr></thead><tbody><tr><td>Sheet thickness limit</td><td>${ridge?'3.0':'1.6'} mm</td><td>Prepared profile ${ridge?'v3':'v2'}</td></tr><tr><td>Bend length limit</td><td>${ridge?'500':'400'} mm</td><td>Prepared profile ${ridge?'v3':'v2'}</td></tr><tr><td>B2 tooling reach</td><td>${status('Not recorded','warn')}</td><td>Needs human setup confirmation</td></tr></tbody></table>`:''}<form id="profile-form" class="profile-form" data-facility="${esc(name)}"><div class="eyebrow">${prepared?'Local onboarding draft':'Workshop capability form'}</div><div class="profile-fields"><label class="field"><span>Main processes</span><input name="processes" maxlength="200" value="${esc(profile.processes||'')}" placeholder="e.g. sheet cutting, CNC bending"></label><label class="field"><span>Machines and tooling</span><textarea name="machines" maxlength="1000" placeholder="List machine models, tool families and setup notes">${esc(profile.machines||'')}</textarea></label><label class="field"><span>Maximum sheet thickness (mm)</span><input name="thickness" type="number" min="0" max="1000" step="0.1" value="${esc(profile.thickness||'')}" placeholder="Optional"></label><label class="field"><span>Maximum bend length (mm)</span><input name="length" type="number" min="0" max="100000" step="1" value="${esc(profile.length||'')}" placeholder="Optional"></label><label class="field span-two"><span>Limits and setup requirements</span><textarea name="limits" maxlength="1000" placeholder="Anything an engineer must confirm before handoff">${esc(profile.limits||'')}</textarea></label></div><div class="profile-save"><button class="button" type="submit">Save local draft</button><span>${profile.savedAt?'Saved in this browser · '+esc(new Date(profile.savedAt).toLocaleString()):'Nothing has been submitted to Chappe or verified by engineering.'}</span></div></form></section>${invited?`<section class="section desk-section" id="received-work"><div class="section-head"><div><h2>No jobs sent yet</h2><p>This invitation preview does not assign Sensor Mount or share an engineer workspace with this browser.</p></div></div><div class="received-row"><div><strong>Ready for engineering review</strong><span>Once account invitations and profile submission run on a hosted server, engineering can confirm this facility and send work.</span></div></div></section>`:`<section class="section desk-section" id="received-work"><div class="section-head"><div><h2>Sensor Mount · Job 1042</h2><p>Prepared drawing A and selective B2 guidance for the five-minute demo.</p></div>${status(state.session?.guideStatus==='approved'?'Release 1 available':'Awaiting engineer approval',state.session?.guideStatus==='approved'?'good':'warn')}</div><div class="received-row"><div><strong>SKW-SM-104</strong><span>Drawing A · Return flange B2 · ${esc(name)}</span></div><a class="text-link" href="#/operator?session=${encodeURIComponent(sessionId())}">Open floor view ↗</a></div><p class="scope-copy">The live demo session shares guide approval and floor issues. The prepared profile is not a workshop attestation.</p></section>`}<section class="section desk-section" id="floor-conversation"><div class="section-head"><div><h2>Questions and flags</h2><p>Issues remain attached to the job, release and B2 operation.</p></div></div>${invited?'<div class="issues-empty">No floor conversation is attached to this invitation preview.</div>':issueList(false)}</section>`)}
  function openIssues(){return (state.session?.issues||[]).filter(i=>!i.answer&&i.status!=='answered')}
  function issueList(engineer){const items=state.session?.issues||[];if(!items.length)return '<div class="issues-empty">No floor feedback yet. Open the phone view and ask Chappe or raise a red flag for B2.</div>';return items.slice().sort((a,b)=>Number(issueMeta(b).red)-Number(issueMeta(a).red)||Date.parse(b.createdAt||0)-Date.parse(a.createdAt||0)).map(i=>{const meta=issueMeta(i);const label=meta.red?'Hard-stop flag':meta.resolved?'Assisted improvement report':i.kind==='flag'?'Direct flag':'Floor question';const stateLabel=i.answer?'Engineer answered':meta.red?'Immediate review':meta.resolved?'Improvement review':'Awaiting engineer';const stateTone=i.answer?'good':meta.red?'bad':meta.resolved?'blue':'warn';return `<article class="issue-row ${meta.red?'issue-row-urgent':''}"><div>${status(stateLabel,stateTone)} <span class="mono">${esc(i.operationId||'B2')}</span> · ${esc(label)}</div><p><strong>${esc(i.body)}</strong></p>${i.reportSummary?`<p class="issue-summary"><strong>Assistant draft:</strong> ${esc(i.reportSummary)}</p>`:''}${i.recommendation?`<p class="issue-summary"><strong>Candidate improvement:</strong> ${esc(i.recommendation)}</p>`:''}<small>Job 1042 · ${state.session?.guideStatus==='approved'?'Release 1':'Draft preview'} · ${esc(i.createdAt?new Date(i.createdAt).toLocaleString():'This session')}</small>${i.answer?`<div class="response"><strong>Engineer-approved response</strong>${esc(i.answer)}<div style="margin-top:8px">${status(issueIsHeld(i)?'B2 hold remains':'No hold is active for this report',issueIsHeld(i)?'warn':'good')}</div></div>`:engineer?`<div class="issue-actions"><button class="button secondary slim" data-respond="${esc(i.id)}">${meta.red?'Review hard stop →':meta.resolved?'Review recommendation →':'Review & respond →'}</button></div>`:''}</article>`}).join('')}
  function issues(){const issue=(state.session?.issues||[]).find(i=>i.id===state.responding);const meta=issue?issueMeta(issue):null;const urgent=urgentIssues();const improvements=improvementReports();return wrap('issues',`${workHead('Engineer workspace / floor feedback','Floor issues','A red flag is a hard stop. Assisted reports are improvement candidates until an engineer decides what changes.',`<a class="button secondary" href="#/operator?session=${encodeURIComponent(sessionId())}">Open phone view</a>`)}${metadata()}<section class="section"><div class="floor-alert-summary" role="status"><strong>${urgent.length} urgent flag${urgent.length===1?'':'s'}</strong><span>${improvements.length} assisted improvement report${improvements.length===1?'':'s'} for this product</span></div><div class="grid-two"><div><div class="section-head"><div><h2>${openIssues().length} items awaiting review</h2><p>Hard-stop flags are shown first. A report from a resolved assist is not a release change or a manufacturing approval.</p></div></div>${issueList(true)}</div><div class="pane">${issue?`<div class="eyebrow">Job 1042 / ${esc(issue.operationId||'B2')} / ${state.session?.guideStatus==='approved'?'Release 1':'Draft preview'}</div><h3 style="margin-top:9px">${esc(meta?.red?'Hard-stop operator flag':meta?.resolved?'Assisted improvement report':issue.kind==='flag'?'Direct operator flag':'Operator question')}</h3><p>${esc(issue.body)}</p>${issue.reportSummary?`<div class="note"><strong>Assistant draft summary.</strong> ${esc(issue.reportSummary)}</div>`:''}${issue.recommendation?`<div class="note"><strong>Candidate improvement.</strong> ${esc(issue.recommendation)}</div>`:''}<div class="note ${meta?.red?'bad':'warn'}">${meta?.red?`B2 is on hold pending your decision. The assistant report is context only; do not infer a setup answer from the drawing alone.`:meta?.resolved?`The operator reports the source-bound assist was sufficient. Review the candidate improvement and decide whether to clarify the guide, revise the design, or leave the release unchanged.`:`This floor question is linked to the exact release and operation. Escalate to a hold if the released sources do not settle it.`}</div><label class="field"><span>${meta?.resolved?'Engineering review outcome':'Your approved response'}</span><textarea id="response-text" maxlength="1000" placeholder="${meta?.resolved?'Record the next action or a guide revision to consider.':'Write a concise clarification grounded in the approved source or ask the operator to keep B2 on hold.'}"></textarea><small>Assistant text is a draft for review; it cannot publish a release or clear a hold.</small></label><label class="checkline"><input id="keep-hold" type="checkbox" ${meta?.resolved?'':'checked'}> ${meta?.resolved?'Set a hold only if your review finds one necessary':'Keep B2 on hold after this answer'}</label><p class="muted" style="font-size:12px">Only an explicit engineering decision can authorise a held operation to resume.</p><button class="button" id="send-response" data-issue="${esc(issue.id)}" ${!hasToken()&&state.mode==='live'?'disabled title="Engineer token absent in this browser"':''}>${meta?.resolved?'Record review outcome →':meta?.red?'Respond to hard stop →':'Approve response →'}</button>${!hasToken()&&state.mode==='live'?'<p class="muted">This browser lacks the engineer token. Start a new session here to respond.</p>':''}`:`<h3>Issue context</h3><p>Select an item to inspect its operation, raw operator statement, and any assistant draft.</p>`}</div></div></section>`)}
  function qr(){const approved=state.session?.guideStatus==='approved';return wrap('qr',`${workHead('Engineer workspace / handoff','QR and drawing label','This demo session link opens its release context and approved guide.',`<a class="button secondary" href="#/review">${approved?'View reviewed guide':'Review guide'}</a>`)}${metadata()}<section class="section"><div class="grid-two equal"><div class="pane"><div class="eyebrow">Print label / prepared example</div><h2 style="margin:9px 0">Sensor Mount <span class="mono">SKW-SM-104</span></h2><p>Drawing revision A · ${approved?'Release 1 approved':'Not released'}</p><div class="qr-pane" style="margin-top:20px"><div class="qr-box" id="qr-box">Generating QR…</div><div><strong>Scan for the part guide</strong><p style="margin:8px 0 16px">${approved?'Opens the engineer-approved B2 guidance and answers for this demo session.':'Approve the guide before treating this as a released handoff.'}</p>${status(approved?'Engineer approved':'Draft · not for floor',approved?'good':'warn')}</div></div></div><div><h2>Operator link</h2><p class="muted">For the pitch, open this link on a phone or scan the label above.</p><div class="link-field"><input id="operator-link" readonly value="${esc(operatorUrl())}" aria-label="Operator link"><button class="button secondary slim" id="copy-link">Copy</button></div><div class="work-actions" style="margin-top:13px"><a class="button" href="${esc(operatorUrl())}">Open phone view ↗</a><button class="button secondary" id="print-label">Print label</button></div><div class="note ${state.mode==='live'?'':'warn'}">${state.mode==='live'?'This link carries the session ID only. Engineer approval token stays in this browser.':'Local preview only: the link works in this browser, but cannot sync to a different phone until the live demo service is configured.'}</div></div></div></section>`)}
  function operator(){
    const s=state.session;
    const op=operations.find(o=>o.id===state.op)||operations[1];
    if(!s)return `${topbar('/operator')}${banner()}<main class="shell chapter"><h1>Part session unavailable</h1><p>${esc(state.error||'Open the demo from engineering to create a session.')}</p><a class="button" href="#/engineer">Go to engineering</a></main>`;
    const issues=(s.issues||[]).filter(i=>(i.operationId||'B2')===state.op);
    const held=issues.some(issueIsHeld);
    const pending=issues.some(i=>issueIsHeld(i)&&!i.answer&&i.status!=='answered');
    const canAssist=state.op==='B2'&&s.guideStatus==='approved';
    const assist=state.assistDraft;
    const feedback=issues.map(i=>{const meta=issueMeta(i);return `<div class="floor-feedback"><div class="eyebrow">${esc(meta.red?'Red flag':meta.resolved?'Assisted report':'Question')} · ${i.answer?'Engineer answered':meta.red?'Sent for immediate review':'Sent to engineering'}</div><p>${esc(i.body)}</p>${i.answer?`<div class="response"><strong>Approved engineering response · Release 1 context</strong>${esc(i.answer)}<div style="margin-top:8px">${status(issueIsHeld(i)?'B2 hold remains':'No hold is active for this report',issueIsHeld(i)?'warn':'good')}</div></div>`:meta.resolved?`<div class="note"><strong>Improvement report queued.</strong> An engineer can review the candidate improvement under this product.</div>`:status(meta.red?'Hard stop awaiting decision':'Pending decision',meta.red?'bad':'warn')}</div>`}).join('');
    const composer=!canAssist?`<section class="section"><div class="note warn">${s.guideStatus!=='approved'?'The guide is still a draft. Engineering must approve it before floor assistance can use this release.':'This prepared live support loop covers B2 only. Select B2 for release-bound help.'}</div></section>`:state.floorMode==='assist'?`<section class="floor-composer" aria-labelledby="floor-assist-title"><div><div class="eyebrow">Chappe Assist / ${esc(state.op)}</div><h2 id="floor-assist-title">Ask about this operation</h2><p class="muted">Your question stays attached to Job 1042, Release 1 and B2. Speak or type, then review the transcript before sending.</p></div><form id="floor-assist-form"><label class="field"><span>Your question</span><textarea id="floor-assist-text" required minlength="4" maxlength="320" placeholder="For example: Which face should I use as the reference?">${esc(state.assistText)}</textarea></label><p class="dictation-note">Voice uses the browser&apos;s dictation service. No raw audio is kept by this demo.</p>${state.speechError?`<p class="floor-message" role="status">${esc(state.speechError)}</p>`:''}<div class="floor-composer-actions"><button class="button secondary" type="button" data-voice-target="assist" aria-pressed="${state.listeningFor==='assist'}">${state.listeningFor==='assist'?'Stop listening':'Speak question'}</button><button class="button" type="submit">Ask Chappe</button></div></form></section>`:state.floorMode==='answer'&&assist?`<section class="floor-composer floor-assist-answer" aria-live="polite"><div><div class="eyebrow">Chappe Assist / source-bound response</div><h2>Check this before acting</h2><p class="assist-question"><strong>You asked:</strong> ${esc(assist.question)}</p><p>${esc(assist.answer)}</p></div><div class="assistant-report"><strong>Automatic engineering review note</strong><span>${esc(assist.recommendation)}</span><small>This is a draft recommendation, not a released fix or a hold clearance.</small></div><div class="floor-composer-actions"><button class="button secondary" type="button" data-assist-outcome="resolved">This resolved it</button><button class="button red" type="button" data-floor-action="flag">Still blocked · flag &amp; hold</button></div></section>`:state.floorMode==='flag'?`<section class="floor-composer floor-flag-composer" aria-labelledby="floor-flag-title"><div><div class="eyebrow">Red flag / ${esc(state.op)}</div><h2 id="floor-flag-title">Stop and flag this issue</h2><p class="muted">This creates a hard stop first, then sends engineering the raw statement and a draft investigation note. Do not wait for the assistant to continue.</p></div><form id="floor-flag-form"><label class="field"><span>What is blocked?</span><textarea id="floor-flag-text" required minlength="4" maxlength="320" placeholder="Describe what you see, what you tried and why you cannot continue.">${esc(state.flagText)}</textarea></label><p class="dictation-note">Voice uses the browser&apos;s dictation service. Review the transcript before sending.</p>${state.speechError?`<p class="floor-message" role="status">${esc(state.speechError)}</p>`:''}<div class="floor-composer-actions"><button class="button secondary" type="button" data-voice-target="flag" aria-pressed="${state.listeningFor==='flag'}">${state.listeningFor==='flag'?'Stop listening':'Speak issue'}</button><button class="button red" type="submit">Send red flag &amp; hold</button></div></form></section>`:'';
    const actionBar=canAssist?`<nav class="floor-action-bar" aria-label="Help with this operation"><button class="button" type="button" data-floor-action="assist">Speak or type question</button><button class="button red" type="button" data-floor-action="flag">Flag &amp; hold</button></nav>`:'';
    return `${topbar('/operator')}${banner()}<main class="phone-page"><div class="phone"><div class="phone-header"><a class="back" href="#/qr">← Drawing / handoff</a><div class="eyebrow" style="margin-top:17px">Job 1042 · ${s.guideStatus==='approved'?'Release 1':'Draft preview'}</div><h1>Sensor Mount</h1><p><span class="mono">SKW-SM-104</span> · Drawing rev A · ${esc(state.facility)}</p></div><div class="phone-inner"><div class="section-head"><div><h2 style="font-size:19px">Choose the area</h2><p>Prepared part illustration and bend labels.</p></div></div><div class="op-chips" aria-label="Choose operation">${operations.map(o=>`<button class="op-chip ${state.op===o.id?'selected':''}" data-op="${o.id}" aria-pressed="${state.op===o.id}" title="${esc(o.title)}">${o.id}</button>`).join('')}</div>${model(state.op)}<section class="section"><div class="eyebrow">Selected / ${esc(state.op)}</div><h2 style="margin:6px 0">${esc(op.title)}</h2>${held?`<div class="step held" role="alert"><div class="eyebrow" style="color:var(--ch-status-conflict)">Hold this operation</div><h3>${pending?'Await engineering decision.':'Engineering answer available · hold remains.'}</h3><p>${pending?'A red flag was sent with this exact job, release and B2 context. Do not continue the affected operation based on an unconfirmed answer.':'Read the approved response below. Engineering has not explicitly cleared this operation to resume.'}</p></div>`:''}${op.guide?`<div class="step"><div class="eyebrow">${s.guideStatus==='approved'?'Engineer-approved · Release 1':'Draft preview · not released'}</div><h3>${s.guideStatus==='approved'?esc(s.guideText):'The detailed B2 guide awaits engineer approval.'}</h3><p>Source: drawing revision A + authored bend manifest. The guide is an aid, not a certified machine sequence.</p></div>`:`<div class="step"><h3>Use the drawing for this routine area.</h3><p>No extra instruction card was approved for ${esc(state.op)}. Its 90° internal-angle target is shown in the prepared drawing and bend manifest.</p></div>`}${feedback}</section>${composer}</div>${actionBar}</div></main>`}
  function phonePreview(){
    const op=operations.find(o=>o.id===state.op)||operations[1];
    return `<header class="topbar">${brand()}<nav class="top-links" aria-label="Primary"><a class="button slim" href="#/engineer">Explore demo ↗</a></nav></header>
      <div class="storage-banner preview-banner"><strong>Prepared phone preview</strong> · Example content only. This is not a live release or engineer approval.</div>
      <main class="phone-page"><div class="phone"><div class="phone-header"><a class="back" href="#/">← About Chappe</a><div class="eyebrow" style="margin-top:17px">Job 1042 · Sample guide preview</div><h1>Sensor Mount</h1><p><span class="mono">SKW-SM-104</span> · Drawing rev A · Prepared example</p></div>
      <div class="phone-inner"><div class="section-head"><div><h2 style="font-size:19px">Choose the area</h2><p>Prepared part illustration and bend labels.</p></div></div>
      <div class="op-chips" aria-label="Choose operation">${operations.map(o=>`<button class="op-chip ${state.op===o.id?'selected':''}" data-op="${o.id}" aria-pressed="${state.op===o.id}" title="${esc(o.title)}">${o.id}</button>`).join('')}</div>
      ${model(state.op)}
      <section class="section"><div class="eyebrow">Selected / ${esc(state.op)}</div><h2 style="margin:6px 0">${esc(op.title)}</h2>${op.guide?`<div class="step"><div class="eyebrow">Sample engineer-reviewed wording · preview only</div><h3>${esc(seed.guideText)}</h3><p>Prepared from drawing revision A and an authored bend manifest. A real engineer must review, correct and approve a release before this can be floor guidance. Tooling clearance remains unknown.</p></div>`:`<div class="step"><h3>No detailed guide proposed for this routine area.</h3><p>The drawing remains the source for ${esc(op.id)}. This preview does not validate the operation or issue instructions.</p></div>`}</section>
      <section class="section"><h2>Questions stay with the operation</h2><p class="muted">In a live approved session, the floor bar opens voice or typed help for this exact release. A resolved question creates an engineer-review improvement candidate; a red flag holds the operation and creates an urgent report. This preview cannot send a message.</p><a class="button" href="#/engineer">Start the live demo →</a><p class="muted" style="font-size:12px;margin-top:13px">To see a real session QR, review and approve B2 in the engineer workspace.</p></section>
      </div></div></main>`;
  }
  function drawQR(){const box=$('#qr-box');if(!box)return;if(!window.QRCode){box.textContent='QR unavailable · use the link';return}box.innerHTML='';try{window.QRCode.toString(operatorUrl(),{type:'svg',width:160,margin:1,color:{dark:'#1d1d1f',light:'#ffffff'}},(err,svg)=>{if(err){box.textContent='QR unavailable · use the link';return}box.innerHTML=svg})}catch{box.textContent='QR unavailable · use the link'}}
  let revealObserver;
  let brandMorph;
  const reduceMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
  function setupBrandMorph(){
    brandMorph=null;
    if(currentRoute()!=='/')return;
    const scene=$('.brand-morph');const canvas=$('#brand-morph-canvas');const context=canvas?.getContext('2d',{alpha:true});
    if(!scene||!canvas||!context)return;
    const sources=Array.from({length:96},(_,index)=>`assets/chappe-morph/frames/frame-${String(index).padStart(3,'0')}.webp`);
    const morph={scene,canvas,context,sources,frames:[],current:-1};
    const draw=index=>{
      const image=morph.frames[index];if(!image||!image.complete||!image.naturalWidth)return;
      context.clearRect(0,0,canvas.width,canvas.height);context.drawImage(image,0,0,canvas.width,canvas.height);
    };
    morph.draw=draw;
    morph.frames=sources.map((source,index)=>{
      const image=new Image();image.decoding='async';
      image.addEventListener('load',()=>{if(brandMorph===morph&&morph.current===index)draw(index)});
      image.src=source;return image;
    });
    brandMorph=morph;
    updateBrandMorph();
  }
  function updateBrandMorph(){
    const morph=brandMorph;if(!morph)return;
    const travel=Math.max(1,morph.scene.offsetHeight-innerHeight);
    const progress=reduceMotion.matches?1:Math.max(0,Math.min(1,(scrollY-morph.scene.offsetTop)/travel));
    const next=Math.round(Math.min(1,progress/.84)*95);
    if(next===morph.current)return;
    morph.current=next;morph.draw(next);
  }
  function setupMotion(){
    revealObserver?.disconnect();document.body.classList.remove('motion-ready');setupBrandMorph();
    if(currentRoute()!=='/'||reduceMotion.matches||!('IntersectionObserver' in window)){updateScrollMotion();return;}
    document.body.classList.add('motion-ready');
    revealObserver=new IntersectionObserver(entries=>{for(const entry of entries){if(entry.isIntersecting){entry.target.classList.add('is-visible');revealObserver.unobserve(entry.target)}}},{threshold:.1,rootMargin:'0px 0px -24px 0px'});
    document.querySelectorAll('.reveal').forEach(el=>revealObserver.observe(el));
    updateScrollMotion();
  }
  let motionFrame=0;
  function updateScrollMotion(){
    if(currentRoute()!=='/')return;
    updateBrandMorph();
    if(reduceMotion.matches)return;
    const section=$('.object-chapter');if(!section)return;
    const rect=section.getBoundingClientRect();const progress=Math.max(0,Math.min(1,(innerHeight-rect.top)/(innerHeight+rect.height)));
    document.documentElement.style.setProperty('--object-turn',`${(progress-.5)*12}deg`);
    const media=$('.hero-image');if(media){const top=media.getBoundingClientRect().top;document.documentElement.style.setProperty('--photo-shift',`${Math.max(-18,Math.min(18,(innerHeight/2-top)*.035))}px`)}
  }
  function updateTopbar(){document.querySelector('.topbar')?.classList.toggle('is-scrolled',window.scrollY>24)}
  window.addEventListener('scroll',()=>{if(motionFrame)return;motionFrame=requestAnimationFrame(()=>{motionFrame=0;updateTopbar();updateScrollMotion()})},{passive:true});
  reduceMotion.addEventListener('change',()=>setupMotion());
  function render(){const r=currentRoute();const page={'/':landing,'/engineer':engineer,'/engineer/job':engineerJob,'/engineer/new':engineerNew,'/review':review,'/manufacturer':manufacturer,'/issues':issues,'/qr':qr,'/operator':operator,'/phone-preview':phonePreview}[r]||landing;app.innerHTML=page();const title={'/':'Make the handoff make sense','/engineer':'Engineering jobs','/engineer/job':'Sensor Mount','/engineer/new':'New job draft','/phone-preview':'Phone preview'}[r]||r.slice(1)[0].toUpperCase()+r.slice(2);document.title=`${title} · Chappe`;if(r==='/qr')drawQR();setupMotion();updateTopbar();}
  document.addEventListener('click',async e=>{
    const scrollTarget=e.target.closest('[data-scroll]');if(scrollTarget){document.getElementById(scrollTarget.dataset.scroll)?.scrollIntoView({behavior:reduceMotion.matches?'auto':'smooth'});return}
    const floorAction=e.target.closest('[data-floor-action]');if(floorAction){state.floorMode=floorAction.dataset.floorAction;state.speechError='';if(state.floorMode==='flag'&&state.assistDraft&&!state.flagText)state.flagText=state.assistDraft.question;render();window.requestAnimationFrame(()=>$(state.floorMode==='flag'?'#floor-flag-text':'#floor-assist-text')?.focus());return}
    const voiceAction=e.target.closest('[data-voice-target]');if(voiceAction){startFloorDictation(voiceAction.dataset.voiceTarget);return}
    const assistOutcome=e.target.closest('[data-assist-outcome]');if(assistOutcome){const draft=state.assistDraft;if(!draft)return;try{await mutate('issue',{kind:'question',operationId:state.op,body:draft.body,reportType:draft.reportType,operatorOutcome:draft.operatorOutcome,reportSummary:draft.reportSummary,recommendation:draft.recommendation});state.assistText='';state.assistDraft=null;state.floorMode='guide';render();toast('Improvement report queued for this product’s engineering review.')}catch(err){toast(err.message)}return}
    const op=e.target.closest('[data-op]');if(op){if(floorRecognition)floorRecognition.stop();state.op=op.dataset.op;state.floorMode='guide';state.assistDraft=null;state.speechError='';render();return}
    const respond=e.target.closest('[data-respond]');if(respond){state.responding=respond.dataset.respond;render();$('#response-text')?.focus();return}
    if(e.target.closest('#publish,#publish-top')){if(state.session?.guideStatus==='approved'){toast('Release 1 is already approved and immutable.');return}if(!isPreparedFacility()){toast('This facility has no verified profile in the demo. Choose a prepared facility to publish.');return}if(state.facility==='Harbour Toolworks'){toast('Resolve the documented facility conflict before publishing.');return}const guideText=($('#guide-text')?.value||state.session?.guideText||'').trim();if(!guideText){toast('Write the B2 guidance before approving.');return}try{await mutate('approve',{guideText});toast('B2 guidance approved and released.');location.hash='#/qr'}catch(err){toast(err.message)}return}
    if(e.target.closest('#send-response')){const answer=($('#response-text')?.value||'').trim();if(!answer){toast('Write an engineer response first.');return}try{await mutate('respond',{issueId:e.target.closest('#send-response').dataset.issue,answer,holdActive:$('#keep-hold')?.checked!==false});state.responding=null;render();toast('Approved answer returned to the floor.')}catch(err){toast(err.message)}return}
    if(e.target.closest('#copy-link')){try{await navigator.clipboard.writeText(operatorUrl());toast('Operator link copied.')}catch{const input=$('#operator-link');input.select();document.execCommand('copy');toast('Operator link copied.')}return}
    if(e.target.closest('#print-label')){window.print();return}
    if(e.target.closest('#new-session')){await createSession();return}
    if(e.target.closest('#add-facility')){state.showInvite=!state.showInvite;render();return}
    if(e.target.closest('#copy-invite')){const input=$('#invite-link');if(!input)return;try{await navigator.clipboard.writeText(input.value)}catch{input.select();document.execCommand('copy')}toast('Invitation preview link copied.');return}
  });
  document.addEventListener('change',e=>{if(e.target.id==='facility'){state.facility=e.target.value;render()}if(e.target.id==='draft-facility')state.draftFacility=e.target.value;if(e.target.id==='source-files')selectFiles(e.target.files)});
  document.addEventListener('input',e=>{if(e.target.id==='floor-assist-text')state.assistText=e.target.value;if(e.target.id==='floor-flag-text')state.flagText=e.target.value;});
  function selectFiles(files){const name=$('#draft-form [name="name"]');if(name)state.draftName=name.value;const facility=$('#draft-facility');if(facility)state.draftFacility=facility.value;const accepted=/\.(sldprt|sldasm|ipt|iam|step|stp|iges|igs|dxf|dwg|stl|obj|glb|pdf)$/i;const all=Array.from(files||[]);const valid=all.filter(f=>accepted.test(f.name));state.uploadFiles=valid.map(f=>({name:f.name,size:f.size}));render();toast(all.length===valid.length?`${valid.length} file${valid.length===1?'':'s'} selected in this browser. No upload or analysis occurred.`:`${all.length-valid.length} unsupported file${all.length-valid.length===1?'':'s'} skipped. No upload occurred.`)}
  document.addEventListener('dragover',e=>{if(e.target.closest('#file-drop')){e.preventDefault();e.target.closest('#file-drop').classList.add('dragging')}});
  document.addEventListener('dragleave',e=>{if(e.target.closest('#file-drop'))e.target.closest('#file-drop').classList.remove('dragging')});
  document.addEventListener('drop',e=>{const zone=e.target.closest('#file-drop');if(zone){e.preventDefault();zone.classList.remove('dragging');selectFiles(e.dataTransfer.files)}});
  document.addEventListener('submit',async e=>{if(e.target.id==='draft-form'){e.preventDefault();const form=new FormData(e.target);const name=String(form.get('name')||'').trim().slice(0,100);const files=state.uploadFiles.length?state.uploadFiles:jobDraft()?.files||[];if(!name||!files.length){toast('Give the draft a name and choose at least one file.');return}const draft={name,facility:String(form.get('facility')||''),files,savedAt:new Date().toISOString()};localStorage.setItem(DRAFT_STORAGE,JSON.stringify(draft));state.draftName=name;state.draftFacility=draft.facility;render();toast('Local draft saved. File names only; no upload occurred.');return}if(e.target.id==='invite-form'){e.preventDefault();const form=new FormData(e.target);const name=String(form.get('name')||'').trim().slice(0,100);const email=String(form.get('email')||'').trim().slice(0,200);if(!name||!email)return;if(['Ridgeway Fabrication','Harbour Toolworks',...customFacilities().map(f=>f.name)].some(x=>x.toLowerCase()===name.toLowerCase())){toast('That manufacturer is already in the list. Select it instead.');return}const existing=customFacilities();localStorage.setItem(FACILITIES_STORAGE,JSON.stringify([...existing,{name,email}]));state.facility=name;state.invitation={name,email,url:inviteUrl(name)};state.showInvite=true;render();toast('Preview link ready. No email was sent.');return}if(e.target.id==='profile-form'){e.preventDefault();const form=new FormData(e.target);const name=e.target.dataset.facility;const profile={processes:String(form.get('processes')||''),machines:String(form.get('machines')||''),thickness:String(form.get('thickness')||''),length:String(form.get('length')||''),limits:String(form.get('limits')||''),savedAt:new Date().toISOString()};const next=profiles();next[name]=profile;localStorage.setItem(PROFILE_STORAGE,JSON.stringify(next));render();toast('Facility draft saved in this browser only.');return}if(e.target.id==='floor-assist-form'){e.preventDefault();if(state.op!=='B2'||state.session?.guideStatus!=='approved'){toast('B2 must be selected in an approved release.');return}const question=($('#floor-assist-text')?.value||'').trim();if(question.length<4){toast('Add a short question before asking Chappe.');return}state.assistText=question;state.assistDraft=buildAssistDraft(question);state.floorMode='answer';state.speechError='';render();return}if(e.target.id==='floor-flag-form'){e.preventDefault();if(state.op!=='B2'||state.session?.guideStatus!=='approved'){toast('B2 must be selected in an approved release.');return}const question=($('#floor-flag-text')?.value||'').trim();if(question.length<4){toast('Add a short statement before raising a red flag.');return}const report=buildFlagDraft(question);try{await mutate('issue',{kind:'flag',operationId:state.op,body:report.body,reportType:report.reportType,operatorOutcome:report.operatorOutcome,reportSummary:report.reportSummary,recommendation:report.recommendation});state.flagText='';state.assistText='';state.assistDraft=null;state.floorMode='guide';render();toast('Red flag sent. B2 is on hold and engineering has an immediate-review report.')}catch(err){toast(err.message)}return}if(e.target.id!=='issue-form')return;e.preventDefault();if(state.op!=='B2'||state.session?.guideStatus!=='approved'){toast('B2 must be selected in an approved release.');return}const kind=e.submitter?.value||'question';const body=($('#issue-body')?.value||'').trim();if(body.length<4){toast('Add a short description before sending.');return}try{await mutate('issue',{kind,operationId:state.op,body});toast(kind==='flag'?'Flag sent. Hold this operation until engineering responds.':'Question sent to engineering. Hold this operation until answered.')}catch(err){toast(err.message)}});
  window.addEventListener('hashchange',async()=>{const requested=query().get('session');if(currentRoute()==='/phone-preview')render();else if(requested&&requested!==sessionId())await initSession(requested);else if(!state.session)await initSession();else render();window.scrollTo(0,0)});
  window.addEventListener('storage',e=>{if([STORAGE,TOKEN_STORAGE].includes(e.key)&&state.mode==='local'){state.session=normalize(getLocal()||seed);render()}});
  setInterval(()=>{if(currentRoute()==='/operator'||currentRoute()==='/issues')refresh()},3500);
  if(currentRoute()==='/phone-preview')render();else initSession(query().get('session'));
})();
